      "url": "https://perthpipepower.com.au/water-leak-detection-perth.html",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Can you guarantee finding a hidden leak without opening a wall?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Access and the suspected source determine what investigation is appropriate. Do not assume that every leak can be located or repaired without opening finishes. The proposed method and any access or restoration work need to be explained before approval."
          }
        },
        {
          "@type": "Question",
          "name": "Does a high water bill prove there is a leaking pipe?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. It is useful context, not a diagnosis. Include any observed water, changes in use and available records. If the concern is at the water meter or supply network, use Water Corporation guidance rather than assuming it is private pipework."
          }
        },
        {
          "@type": "Question",
          "name": "Can a hidden water leak cause a high bill without visible water damage?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes, a concealed leak is possible without visible damage. A bill increase alone is insufficient to diagnose one. Read the explanation."
          }
        },
        {
          "@type": "Question",
          "name": "Why is my water meter moving when no water is being used?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Flow without expected use can indicate a leak or a fixture still drawing water. It cannot locate the source. Read the explanation."
          }
        },
        {
          "@type": "Question",
          "name": "Do I need to diagnose the problem first?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Describe the observable change and property context. We inspect the affected area on site to establish the cause and confirm the repair scope. If more access is needed, we agree it with you first."
          }
        },
        {
          "@type": "Question",
          "name": "Can I send photos?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Photos are optional: email safely taken photos to maxinemaintenance.au@outlook.com. You can contact us without photos. Do not approach a hazard, remove covers or dismantle equipment to take a photo."
          }
        },
        {
          "@type": "Question",
          "name": "Can you help with a hidden water leak?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Describe the property area, any visible moisture and changes you have noticed. This helps us understand the request before work is arranged."
          }
        },
        {
          "@type": "Question",
          "name": "What should I include in a leak enquiry?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Include the address, affected room or outdoor area, when the issue began, whether water is active and any safe photos."
          }
        },
        {
          "@type": "Question",
          "name": "What if water is near electrical equipment?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Keep clear of the area and do not touch wet electrical equipment. If there is immediate danger, move to safety and call 000."
          }
        },
        {
          "@type": "Question",
          "name": "Are locating the leak and repairing it the same job?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "They can be separate parts of the scope. We explain the investigation, access and proposed repair before work proceeds, and identify any additional access or reinstatement work in the written quote."
          }
        }
      ]
    }
